#include <bits/stdc++.h>
using namespace std;

int findCenter(int n, const vector<vector<int>>& adj) {
    vector<int> dist(n + 1, -1), parent(n + 1, 0);
    queue<int> q;

    dist[1] = 0;
    q.push(1);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }

    int A = 1;
    for (int i = 2; i <= n; ++i) {
        if (dist[i] > dist[A]) A = i;
    }

    fill(dist.begin(), dist.end(), -1);
    fill(parent.begin(), parent.end(), 0);

    dist[A] = 0;
    q.push(A);
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }

    int B = A;
    for (int i = 1; i <= n; ++i) {
        if (dist[i] > dist[B]) B = i;
    }

    int diameter = dist[B];
    vector<int> path;
    for (int v = B; v != 0; v = parent[v]) {
        path.push_back(v);
    }
    reverse(path.begin(), path.end());

    return path[diameter / 2];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> circle(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int A, B;
        cin >> A >> B;
        circle[A].push_back(B);
        circle[B].push_back(A);
    }

    int centerCircle = findCenter(N, circle);

    vector<vector<int>> square(M + 1);
    for (int i = 0; i < M - 1; ++i) {
        int X, Y;
        cin >> X >> Y;
        square[X].push_back(Y);
        square[Y].push_back(X);
    }

    int centerSquare = findCenter(M, square);

    cout << centerCircle << ' ' << centerSquare << '\n';

    return 0;
}
